param location string = resourceGroup().location
param environmentName string = 'nexus-prod-env'
param apiImageName string

// 1. Managed Identity
resource nexusIdentity 'Microsoft.ManagedIdentity/userAssignedIdentities@2023-01-31' = {
  name: 'id-nexus-backend'
  location: location
}

// 2. Azure OpenAI Cognitive Services Account
resource openAiAccount 'Microsoft.CognitiveServices/accounts@2023-05-01' existing = {
  name: 'cog-nexus-prod'
}

// 3. Grant Managed Identity Cognitive Services OpenAI User Role
// Role ID: 5e0dc2a4-4d15-46f3-a1c2-ef477502c46f
resource openAiRoleAssignment 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: guid(openAiAccount.id, nexusIdentity.id, 'CognitiveServicesOpenAIUser')
  scope: openAiAccount
  properties: {
    roleDefinitionId: subscriptionResourceId('Microsoft.Authorization/roleDefinitions', '5e0dc2a4-4d15-46f3-a1c2-ef477502c46f')
    principalId: nexusIdentity.properties.principalId
    principalType: 'ServicePrincipal'
  }
}

// 4. Azure Container App for WebApi
resource containerApp 'Microsoft.App/containerApps@2023-05-01' = {
  name: 'app-nexus-api'
  location: location
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${nexusIdentity.id}': {}
    }
  }
  properties: {
    managedEnvironmentId: resourceId('Microsoft.App/managedEnvironments', environmentName)
    configuration: {
      ingress: {
        external: true
        targetPort: 8080
        transport: 'auto'
      }
    }
    template: {
      containers: [
        {
          name: 'nexus-api'
          image: apiImageName
          env: [
            { name: 'AZURE_CLIENT_ID', value: nexusIdentity.properties.clientId }
            { name: 'AzureOpenAI__Endpoint', value: openAiAccount.properties.endpoint }
            { name: 'ASPNETCORE_ENVIRONMENT', value: 'Production' }
          ]
          resources: {
            cpu: json('1.0')
            memory: '2.0Gi'
          }
        }
      ]
      scale: {
        minReplicas: 2
        maxReplicas: 10
        rules: [
          {
            name: 'http-rule'
            http: {
              metadata: {
                concurrentRequests: '50'
              }
            }
          }
        ]
      }
    }
  }
}
